function AdminUsers(){const {lang,t}=useLocale(),[ver,setVer]=useState(0),state=useFetch('/admin/users',[ver]),[notice,setNotice,toast]=useNotify();const update=async(id,payload)=>{try{await api('/admin/users/'+id,{method:'PATCH',body:JSON.stringify(payload)});setVer(x=>x+1);setNotice(t('success'));}catch(e){setNotice(e.message);}};return <div className="admin-card"><p className="hint">{lang==='fa'?'برای هر کاربر می‌توانید نقش و وضعیت حساب را تعیین کنید. دسترسی مدیر اصلی محافظت می‌شود.':'Set user roles and account status. The last active admin is protected.'}</p><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>{t('name')}</th><th>{t('email')}</th><th>{lang==='fa'?'نقش':'Role'}</th><th>{t('status')}</th><th>{lang==='fa'?'ثبت‌نام':'Registered'}</th></tr></thead><tbody>{state.data?.items?.map(u=><tr key={u.id}><td>{u.name}</td><td>{u.email}</td><td><select value={u.role} onChange={e=>update(u.id,{role:e.target.value})}>{['customer','support','editor','admin'].map(r=><option key={r}>{r}</option>)}</select></td><td><select value={u.status} onChange={e=>update(u.id,{status:e.target.value})}><option value="active">active</option><option value="blocked">blocked</option></select></td><td>{u.created_at}</td></tr>)}</tbody></table></div>{toast}</div>;}
function AdminCoupons(){const {lang,t,money}=useLocale(),[form,setForm]=useState({code:'',kind:'percent',value:10,min_total:0,max_uses:0,expires_at:''}),[ver,setVer]=useState(0),state=useFetch('/admin/coupons',[ver]),[notice,setNotice,toast]=useNotify();const add=async e=>{e.preventDefault();try{await api('/admin/coupons',{method:'POST',body:JSON.stringify(form)});setForm({code:'',kind:'percent',value:10,min_total:0,max_uses:0,expires_at:''});setVer(x=>x+1);setNotice(t('success'));}catch(e){setNotice(e.message);}};const update=async(c,payload)=>{try{await api('/admin/coupons/'+encodeURIComponent(c.code),{method:'PATCH',body:JSON.stringify(payload)});setVer(x=>x+1);setNotice(t('success'));}catch(e){setNotice(e.message);}};return <><div className="admin-card"><h3>{lang==='fa'?'ساخت کد تخفیف':'Create coupon'}</h3><form className="coupon-form" onSubmit={add}><label>Code<input required value={form.code} onChange={e=>setForm(f=>({...f,code:e.target.value.toUpperCase()}))} placeholder="STAR10"/></label><label>Type<select value={form.kind} onChange={e=>setForm(f=>({...f,kind:e.target.value}))}><option value="percent">%</option><option value="fixed">IRT</option></select></label><label>Value<input type="number" min="1" required value={form.value} onChange={e=>setForm(f=>({...f,value:+e.target.value}))}/></label><label>Min total<input type="number" min="0" value={form.min_total} onChange={e=>setForm(f=>({...f,min_total:+e.target.value}))}/></label><label>Max uses (0=∞)<input type="number" min="0" value={form.max_uses} onChange={e=>setForm(f=>({...f,max_uses:+e.target.value}))}/></label><label>Expiry<input type="date" value={form.expires_at} onChange={e=>setForm(f=>({...f,expires_at:e.target.value}))}/></label><button className="btn btn-admin"><Plus size={17}/>{t('create')}</button></form></div><div className="admin-card"><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Code</th><th>Type</th><th>Value</th><th>Usage</th><th>Expiry</th><th>Status</th></tr></thead><tbody>{state.data?.items?.map(c=><tr key={c.code}><td><code>{c.code}</code></td><td>{c.kind}</td><td>{c.kind==='percent'?c.value+'%':money(c.value)}</td><td>{c.used_count} / {c.max_uses||'∞'}</td><td>{c.expires_at||'—'}</td><td><button className={'chip-toggle '+(c.active?'on':'')} onClick={()=>update(c,{active:!c.active})}>{c.active?'active':'disabled'}</button></td></tr>)}</tbody></table></div></div>{toast}</>;}
