function AdminNewsletter(){const {lang}=useLocale(),[ver,setVer]=useState(0),state=useFetch('/admin/newsletter',[ver]),[notice,setNotice,toast]=useNotify();const remove=async e=>{if(!confirm('Remove subscriber?'))return;try{await api('/admin/newsletter/'+encodeURIComponent(e),{method:'DELETE'});setVer(x=>x+1);setNotice('Removed');}catch(e){setNotice(e.message);}};const download=()=>{const text='email,subscribed_at\n'+(state.data?.items||[]).map(o=>`${JSON.stringify(o.email)},${o.created_at}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));a.download='asteria-subscribers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};return <div className="admin-card"><div className="admin-card-head"><h3>{lang==='fa'?'مشترکان خبرنامه':'Newsletter subscribers'}</h3><button className="btn btn-admin" onClick={download}><Download size={17}/> CSV</button></div><div className="admin-table-wrap"><table className="admin-table"><tbody>{state.data?.items?.map(s=><tr key={s.email}><td>{s.email}</td><td>{s.created_at}</td><td><button className="tiny-button danger" onClick={()=>remove(s.email)}><Trash2 size={16}/></button></td></tr>)}</tbody></table>{!state.loading&&!state.data?.items?.length&&<Empty/>}</div>{toast}</div>;}
