function AdminSettings(){const {lang,t}=useLocale(),state=useFetch('/admin/settings'),[values,setValues]=useState(null),[notice,setNotice,toast]=useNotify(),[busy,setBusy]=useState(false);useEffect(()=>{if(state.data)setValues(state.data);},[state.data]);const save=async e=>{e.preventDefault();setBusy(true);try{const updated=await api('/admin/settings',{method:'PATCH',body:JSON.stringify(Object.fromEntries(Object.entries(values).filter(([key])=>key!=='siteBuilder')))});setValues(updated);setNotice(t('success'));}catch(e){setNotice(e.message);}finally{setBusy(false);}};if(!values)return <Spinner/>;return <div className="admin-card settings-card"><form onSubmit={save}><div className="settings-grid">{Object.entries(values).filter(([key])=>key!=='siteBuilder').map(([key,value])=><label key={key}>{lang==='fa'?settingDescriptions[key]||key:key}{typeof value==='boolean'?<select value={value?'true':'false'} onChange={e=>setValues(v=>({...v,[key]:e.target.value==='true'}))}><option value="true">true</option><option value="false">false</option></select>:(key.toLowerCase().includes('desc')||key.toLowerCase().includes('note'))?<textarea rows="3" value={value} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/>:<input value={value} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/>}</label>)}</div><button className="btn btn-admin" disabled={busy}><Save size={17}/>{t('save')}</button></form>{toast}</div>;}
