function DynamicPage(){const {slug}=useParams();return <PageContent slug={slug}/>;}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
function CourseLessons({slug}){const {lang,t}=useLocale(),state=useFetch('/course/'+encodeURIComponent(slug)+'/lessons'),[open,setOpen]=useState(null);return <div className="course-lessons"><div className="eyebrow">COURSE CURRICULUM</div><h3>{lang==='fa'?'درس‌های این دوره':'Course lessons'}</h3><p className="hint">{lang==='fa'?'درس‌های نمونه بدون خرید قابل مطالعه‌اند. پس از تأیید پرداخت، تمام درس‌ها در حساب خریدار در دسترس قرار می‌گیرند.':'Preview lessons are free. All lessons unlock once payment is confirmed for your signed-in account.'}</p>{state.loading?<Spinner/>:state.data?.items?.length?state.data.items.map((lesson,i)=><div className="lesson-entry" key={lesson.id}><button type="button" onClick={()=>setOpen(open===lesson.id?null:lesson.id)}><span className="lesson-index">{String(i+1).padStart(2,'0')}</span><span>{lesson['title_'+lang]}</span>{lesson.locked?<Lock size={16}/>:<ChevronDown size={16}/>}</button>{open===lesson.id&&<div className="lesson-content">{lesson.locked?<p>{lang==='fa'?'برای دسترسی به این درس باید دوره را خریداری کنید و پرداخت تأیید شود.':'Purchase the course and wait for payment confirmation to unlock this lesson.'}</p>:<><p>{lesson['body_'+lang]}</p>{lesson.video_url&&<VideoPlayer url={lesson.video_url} title={lesson['title_'+lang]}/>}</>}</div>}</div>):<p className="hint">{t('noItems')}</p>}</div>;}
function AdminCategories(){const {lang,t}=useLocale(),[ver,setVer]=useState(0),state=useFetch('/admin/categories',[ver]),[form,setForm]=useState({kind:'article',slug:'',title_fa:'',title_en:'',sort_order:0}),[notice,setNotice,toast]=useNotify();const submit=async e=>{e.preventDefault();try{await api('/admin/categories',{method:'POST',body:JSON.stringify(form)});setForm({kind:'article',slug:'',title_fa:'',title_en:'',sort_order:0});setVer(x=>x+1);setNotice(t('success'));}catch(e){setNotice(e.message);}};const remove=async id=>{if(!confirm(lang==='fa'?'دسته حذف شود؟':'Delete this category?'))return;try{await api('/admin/categories/'+id,{method:'DELETE'});setVer(x=>x+1);}catch(e){setNotice(e.message);}};const rename=async(c,key)=>{const value=window.prompt(key==='title_fa'?'نام فارسی':'English title',c[key]);if(!value)return;try{await api('/admin/categories/'+c.id,{method:'PATCH',body:JSON.stringify({[key]:value})});setVer(x=>x+1);}catch(e){setNotice(e.message);}};return <><div className="admin-card"><h3>{lang==='fa'?'افزودن دسته‌بندی':'Create category'}</h3><form className="coupon-form" onSubmit={submit}><label>{t('category')}<select value={form.kind} onChange={e=>setForm(f=>({...f,kind:e.target.value}))}>{['article','product','course','service'].map(kind=><option key={kind}>{kind}</option>)}</select></label><label>Slug<input required value={form.slug} onChange={e=>setForm(f=>({...f,slug:e.target.value}))} placeholder="fundamentals"/></label><label>فارسی<input required value={form.title_fa} onChange={e=>setForm(f=>({...f,title_fa:e.target.value}))}/></label><label>English<input required value={form.title_en} onChange={e=>setForm(f=>({...f,title_en:e.target.value}))}/></label><label>{t('sort')}<input type="number" value={form.sort_order} onChange={e=>setForm(f=>({...f,sort_order:+e.target.value}))}/></label><button className="btn btn-admin"><Plus size={17}/>{t('create')}</button></form></div><div className="admin-card"><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Kind</th><th>Slug</th><th>فارسی</th><th>English</th><th>{lang==='fa'?'عملیات':'Actions'}</th></tr></thead><tbody>{state.data?.items?.map(c=><tr key={c.id}><td>{c.kind}</td><td><code>{c.slug}</code></td><td>{c.title_fa}</td><td>{c.title_en}</td><td><div className="table-actions"><button onClick={()=>rename(c,'title_fa')}><Edit3 size={16}/></button><button onClick={()=>rename(c,'title_en')}><Globe2 size={16}/></button><button className="danger" onClick={()=>remove(c.id)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table></div></div>{toast}</>;}
function AdminLessons(){const {lang,t}=useLocale(),courses=useFetch('/admin/content?kind=course'),[selected,setSelected]=useState(''),[ver,setVer]=useState(0),[editing,setEditing]=useState(null),[form,setForm]=useState({title_fa:'',title_en:'',body_fa:'',body_en:'',video_url:'',sort_order:0,preview:false}),[notice,setNotice,toast]=useNotify();useEffect(()=>{if(!selected&&courses.data?.items?.length)setSelected(courses.data.items[0].id);},[courses.data]);const state=useFetch('/admin/lessons?courseId='+encodeURIComponent(selected),[ver]);const start=item=>{setEditing(item?.id||'new');setForm(item?{...item,preview:!!item.preview}:{title_fa:'',title_en:'',body_fa:'',body_en:'',video_url:'',sort_order:0,preview:false});};const change=(k,v)=>setForm(f=>({...f,[k]:v}));const save=async e=>{e.preventDefault();try{const url=editing==='new'?'/admin/lessons':'/admin/lessons/'+editing;await api(url,{method:editing==='new'?'POST':'PATCH',body:JSON.stringify({...form,course_id:selected})});setVer(x=>x+1);setEditing(null);setNotice(t('success'));}catch(e){setNotice(e.message);}};const remove=async id=>{if(!confirm(lang==='fa'?'این درس حذف شود؟':'Delete this lesson?'))return;try{await api('/admin/lessons/'+id,{method:'DELETE'});setVer(x=>x+1);setNotice(t('success'));}catch(e){setNotice(e.message);}};return <><div className="admin-panel-toolbar"><label>{lang==='fa'?'انتخاب دوره':'Select course'}<select value={selected} onChange={e=>{setSelected(e.target.value);setEditing(null);}}>{courses.data?.items?.map(c=><option key={c.id} value={c.id}>{c['title_'+lang]}</option>)}</select></label><button className="btn btn-admin" onClick={()=>start(null)} disabled={!selected}><Plus size={17}/>{lang==='fa'?'درس جدید':'New lesson'}</button></div>{editing&&<div className="admin-card editor-card"><div className="editor-head"><h2>{lang==='fa'?'ویرایش درس':'Edit lesson'}</h2><button className="tiny-button" onClick={()=>setEditing(null)}><X size={18}/></button></div><form onSubmit={save} className="stack-form"><div className="form-2"><label>عنوان فارسی<input required value={form.title_fa} onChange={e=>change('title_fa',e.target.value)}/></label><label>Title English<input required value={form.title_en} onChange={e=>change('title_en',e.target.value)}/></label></div><div className="form-2"><label>متن فارسی<textarea rows="8" value={form.body_fa} onChange={e=>change('body_fa',e.target.value)}/></label><label>English body<textarea rows="8" value={form.body_en} onChange={e=>change('body_en',e.target.value)}/></label></div><div className="form-2"><label>{lang==='fa'?'لینک ویدئو YouTube / Aparat / فایل عمومی':'YouTube / Aparat / hosted video URL'}<input dir="ltr" value={form.video_url} onChange={e=>change('video_url',e.target.value)}/></label><label>{t('sort')}<input type="number" value={form.sort_order} onChange={e=>change('sort_order',+e.target.value)}/></label></div><label className="checkbox-line"><input type="checkbox" checked={!!form.preview} onChange={e=>change('preview',e.target.checked)}/>{lang==='fa'?'پیش‌نمایش رایگان':'Free preview lesson'}</label><button className="btn btn-admin"><Save size={17}/>{t('save')}</button></form></div>}<div className="admin-card"><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>{t('title')}</th><th>{t('sort')}</th><th>{lang==='fa'?'نوع دسترسی':'Access'}</th><th>{lang==='fa'?'عملیات':'Actions'}</th></tr></thead><tbody>{state.data?.items?.map(l=><tr key={l.id}><td><strong>{l['title_'+lang]}</strong></td><td>{l.sort_order}</td><td><span className={'status-label '+(l.preview?'published':'draft')}>{l.preview?'preview':'paid access'}</span></td><td><div className="table-actions"><button onClick={()=>start(l)}><Edit3 size={16}/></button><button className="danger" onClick={()=>remove(l.id)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table>{!state.loading&&!state.data?.items?.length&&<Empty/>}</div></div>{toast}</>;}
